INSERT INTO governance_committees (name,mandate,independence_level) SELECT 'Audit, Risk & Assurance Committee','Oversee financial reporting, risk, internal controls, audit, compliance and assurance reporting.','High' WHERE NOT EXISTS (SELECT 1 FROM governance_committees WHERE name='Audit, Risk & Assurance Committee');
INSERT INTO governance_committees (name,mandate,independence_level) SELECT 'People, Remuneration & Succession Committee','Oversee executive remuneration principles, succession planning, leadership capability and key-person continuity.','High' WHERE NOT EXISTS (SELECT 1 FROM governance_committees WHERE name='People, Remuneration & Succession Committee');
INSERT INTO governance_committees (name,mandate,independence_level) SELECT 'Investment & Capital Committee','Review major investments, financing structures, capital allocation and portfolio exposure within delegated authority.','Medium' WHERE NOT EXISTS (SELECT 1 FROM governance_committees WHERE name='Investment & Capital Committee');
INSERT INTO governance_committees (name,mandate,independence_level) SELECT 'Indigenous & Community Stewardship Committee','Review projects and transactions with material indigenous, customary or community implications and monitor benefit commitments.','High' WHERE NOT EXISTS (SELECT 1 FROM governance_committees WHERE name='Indigenous & Community Stewardship Committee');
INSERT INTO governance_committees (name,mandate,independence_level) SELECT 'Strategy & Continental Expansion Committee','Review long-term strategy, regional entry, country formation and major strategic partnerships.','Medium' WHERE NOT EXISTS (SELECT 1 FROM governance_committees WHERE name='Strategy & Continental Expansion Committee');
INSERT INTO governance_roles (role_name,layer,authority_scope,accountability_to) SELECT 'Chair of the Board','Board','Board agenda, oversight and governance leadership without assuming executive management authority.','Board' WHERE NOT EXISTS (SELECT 1 FROM governance_roles WHERE role_name='Chair of the Board');
INSERT INTO governance_roles (role_name,layer,authority_scope,accountability_to) SELECT 'Group Chief Executive Officer','Executive','Group strategy execution, operating performance and delegated management authority.','Board' WHERE NOT EXISTS (SELECT 1 FROM governance_roles WHERE role_name='Group Chief Executive Officer');
INSERT INTO governance_roles (role_name,layer,authority_scope,accountability_to) SELECT 'Company Secretary / Governance Officer','Board','Governance records, notices, resolutions, registers and procedural integrity.','Board' WHERE NOT EXISTS (SELECT 1 FROM governance_roles WHERE role_name='Company Secretary / Governance Officer');
INSERT INTO governance_roles (role_name,layer,authority_scope,accountability_to) SELECT 'Chief Risk & Assurance','Assurance','Independent risk, control and assurance oversight across the Group.','Board / Audit Committee' WHERE NOT EXISTS (SELECT 1 FROM governance_roles WHERE role_name='Chief Risk & Assurance');
INSERT INTO governance_roles (role_name,layer,authority_scope,accountability_to) SELECT 'Indigenous & Community Stewardship Lead','Stewardship','Institutional safeguards, community engagement standards and benefit-commitment monitoring.','Board / Stewardship Committee' WHERE NOT EXISTS (SELECT 1 FROM governance_roles WHERE role_name='Indigenous & Community Stewardship Lead');
INSERT INTO reserved_matters (name,category,approval_level,description,protected) SELECT 'Change to constitutional purpose','Constitution','Shareholder / Board special approval','Any fundamental change to the Group purpose or protected constitutional mandate.',true WHERE NOT EXISTS (SELECT 1 FROM reserved_matters WHERE name='Change to constitutional purpose');
INSERT INTO reserved_matters (name,category,approval_level,description,protected) SELECT 'Major strategic asset disposition','Assets','Board + applicable shareholder approval','Sale, transfer or encumbrance of a material strategic asset outside approved ordinary-course authority.',true WHERE NOT EXISTS (SELECT 1 FROM reserved_matters WHERE name='Major strategic asset disposition');
INSERT INTO reserved_matters (name,category,approval_level,description,protected) SELECT 'Material related-party transaction','Integrity','Independent review + Board approval','Material transaction involving a director, officer, shareholder or connected person.',true WHERE NOT EXISTS (SELECT 1 FROM reserved_matters WHERE name='Material related-party transaction');
INSERT INTO reserved_matters (name,category,approval_level,description,protected) SELECT 'Indigenous or community rights-impacting transaction','Stewardship','Enhanced review + Board approval','Transaction that may materially affect legitimate indigenous, customary or community rights or agreed benefits.',true WHERE NOT EXISTS (SELECT 1 FROM reserved_matters WHERE name='Indigenous or community rights-impacting transaction');
INSERT INTO reserved_matters (name,category,approval_level,description,protected) SELECT 'Formation or dissolution of material subsidiary/SPV','Structure','Board approval + legal review','Creation, merger, disposal or dissolution of a material subsidiary or special purpose vehicle.',false WHERE NOT EXISTS (SELECT 1 FROM reserved_matters WHERE name='Formation or dissolution of material subsidiary/SPV');
INSERT INTO reserved_matters (name,category,approval_level,description,protected) SELECT 'Entry into a new African jurisdiction','Expansion','Board approval + local legal review','Establishment of a country operation or regulated activity in a new jurisdiction.',false WHERE NOT EXISTS (SELECT 1 FROM reserved_matters WHERE name='Entry into a new African jurisdiction');