CREATE TABLE IF NOT EXISTS governance_committees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, mandate text NOT NULL, independence_level text NOT NULL, status text NOT NULL DEFAULT 'Planned', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reserved_matters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, category text NOT NULL, approval_level text NOT NULL, description text NOT NULL, protected boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS governance_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_name text NOT NULL UNIQUE, layer text NOT NULL, authority_scope text NOT NULL, accountability_to text, status text NOT NULL DEFAULT 'Active');
